from author import add, save, write
add(138,'''import {deploymentDemo} from '../../shared/deployment-demo.mjs';await deploymentDemo('persistence');''','The Compose stack builds, writes a task, replaces only api1, and verifies the task survives in PostgreSQL.','Run node tools/setup.mjs first. This uses deployment/compose.yaml, a separate local project from the database fixtures. Named volumes are retained during normal teardown; no docker compose down -v is issued.',mode='docker')
add(139,'''import {pgLab} from '../../shared/postgres.mjs';import {buildTaskApi} from '../../shared/task-api.mjs';import {randomBytes} from 'node:crypto';import assert from 'node:assert/strict';await using db=await pgLab();let unavailable=false;const pool={query(...args){if(unavailable)throw Error('injected DB outage');return db.pool.query(...args);}};const app=await buildTaskApi({pool,key:randomBytes(32)});try{await app.ready();app.courseState.started=false;assert.equal((await app.inject('/ready')).statusCode,503);app.courseState.started=true;assert.equal((await app.inject('/ready')).statusCode,200);unavailable=true;assert.equal((await app.inject('/ready')).statusCode,503);assert.equal((await app.inject('/live')).statusCode,200);unavailable=false;app.courseState.stopping=true;assert.equal((await app.inject('/ready')).statusCode,503);console.log('startup=503, healthy=200, injected dependency outage=503 with live=200, stopping=503');}finally{await app.close();}''','Readiness changes independently of liveness. Dependency failure is injected at the pool boundary, not falsely reported as a physical database outage.',mode='postgres',deps=['pg','fastify','jose'])
add(140,'''import {pgLab} from '../../shared/postgres.mjs';import {Pool} from 'pg';import {buildTaskApi,registerAndLogin} from '../../shared/task-api.mjs';import {randomBytes} from 'node:crypto';import assert from 'node:assert/strict';await using db=await pgLab();const pools=[1,2].map(()=>new Pool({...db.pool.options,max:10})),key=randomBytes(32),apps=await Promise.all(pools.map(pool=>buildTaskApi({pool,key})));try{const user=await registerAndLogin(apps[0]);const made=await apps[0].inject({method:'POST',url:'/tasks',headers:user.headers,payload:{title:'shared persistent task'}});const response=await apps[1].inject({url:'/tasks/'+made.json().id,headers:user.headers});assert.equal(response.statusCode,200);console.log({replicas:2,apiConnectionCap:pools.reduce((n,p)=>n+p.options.max,0),exampleWithOverhead:30,exampleBudget:50,sharedTask:response.json().title});}finally{await Promise.all(apps.map(x=>x.close()));await Promise.all(pools.map(x=>x.end()));}''','Two actual app instances with independent pools and a shared signing key read the same PostgreSQL task.','The example validates shared data and a connection-budget allocation. For the real two-container reverse-proxy rehearsal, run Prompt 138 or 155; deployment/nginx.conf supplies the NGINX upstream.',mode='postgres',deps=['pg','fastify','jose'])
add(141,'''import {pgLab} from '../../shared/postgres.mjs';import assert from 'node:assert/strict';await using db=await pgLab();const {rows:[task]}=await db.pool.query("INSERT INTO tasks(title) VALUES('original') RETURNING id");await db.pool.query('ALTER TABLE tasks ADD COLUMN display_title TEXT');await db.pool.query('UPDATE tasks SET title=$1,display_title=$1 WHERE id=$2',['v2 writes both',task.id]);await db.pool.query('UPDATE tasks SET title=$1 WHERE id=$2',['v1 old writer',task.id]);let row=(await db.pool.query('SELECT title,display_title FROM tasks WHERE id=$1',[task.id])).rows[0];assert.notEqual(row.title,row.display_title);console.log('During overlap read authoritative title:',row.title);await db.pool.query('UPDATE tasks SET display_title=title');row=(await db.pool.query('SELECT title,display_title FROM tasks WHERE id=$1',[task.id])).rows[0];assert.equal(row.title,row.display_title);console.log('After old writers drained, final catch-up backfill:',row);''','Mixed versions read the old authoritative field. After old writers drain, a catch-up backfill repairs even non-null stale derived values.','The final catch-up intentionally copies ALL authoritative title values, rather than only NULL values: a v1 writer can leave a non-null display_title stale. Keep additive columns throughout the rollback window; contract in a later release.',mode='postgres',deps=['pg'])
add(142,'''import {execFileSync} from 'node:child_process';import {Pool} from 'pg';import {fileURLToPath} from 'node:url';import {randomUUID} from 'node:crypto';import {pgLab} from '../../shared/postgres.mjs';import {assert} from '../../shared/lab.mjs';await using source=await pgLab();const name='restore_'+randomUUID().replaceAll('-',''),url=new URL(process.env.DATABASE_URL),admin=new Pool({connectionString:url.href,max:1});let restored;const compose=fileURLToPath(new URL('../../compose.yaml',import.meta.url)),env=fileURLToPath(new URL('../../.env',import.meta.url));const docker=args=>execFileSync('docker',['compose','--env-file',env,'-f',compose,...args]);try{await source.pool.query("INSERT INTO tasks(title) VALUES('backup fixture')");await admin.query('CREATE DATABASE '+name);const archive=docker(['exec','-T','db','pg_dump','-U','course','-d','course_lab','--format=custom','--schema='+source.schema]);execFileSync('docker',['compose','--env-file',env,'-f',compose,'exec','-T','db','pg_restore','-U','course','--dbname='+name,'--exit-on-error','--no-owner'],{input:archive});url.pathname='/'+name;restored=new Pool({connectionString:url.href,options:'-c search_path='+source.schema});assert.equal((await restored.query('SELECT title FROM tasks')).rows[0].title,'backup fixture');console.log('actual pg_dump archive restored into separate database; fixture verified');}finally{await restored?.end();await admin.query('DROP DATABASE IF EXISTS '+name);await admin.end();}''','A real custom-format PostgreSQL archive restores into a fresh, separately named database and its fixture is checked before cleanup.','The Docker container supplies pg_dump/pg_restore, avoiding a required host CLI installation. Only this generated restore database and this lesson’s private schema are removed.',mode='docker+postgres',deps=['pg'])
add(143,'''import {handler} from './src/index.mjs';import {assert,spawnNode} from '../../shared/lab.mjs';const first=await handler({name:'course'}),warm=await handler({name:'course'});console.log({first,warm});assert.equal(first.invocations,1);assert.equal(warm.invocations,2);const fresh=await spawnNode(['--input-type=module','--eval',"import {handler} from './src/index.mjs';console.log(JSON.stringify(await handler({name:'course'})));"]);assert.equal(JSON.parse(fresh.stdout).invocations,1);console.log('fresh process counter=1; same environment counter=2');''','Actual Node invocations demonstrate warm module state versus a fresh process. The supplied SAM template can be invoked locally with SAM CLI and Docker.','Run sam build, then sam local invoke HelloFunction --event events/event.json from this folder. AWS controls the managed runtime patch; SAM execution has a separate external-tool prerequisite.',files={'src/index.mjs':"let invocations=0;export const handler=async event=>{invocations++;return{invocations,name:event.name??null};};",'template.yaml':'Transform: AWS::Serverless-2016-10-31\nResources:\n  HelloFunction:\n    Type: AWS::Serverless::Function\n    Properties:\n      CodeUri: src/\n      Handler: index.handler\n      Runtime: nodejs26.x','events/event.json':'{"name":"course"}'})
add(144,'''import {execFile} from 'node:child_process';import {promisify} from 'node:util';import {fileURLToPath} from 'node:url';import {assert,fs,temp,join,spawnNode} from '../../shared/lab.mjs';await using lab=await temp();const binary=join(lab.path,process.platform==='win32'?'hello.exe':'hello'),config=join(lab.path,'sea.json');await fs.writeFile(config,JSON.stringify({main:fileURLToPath(new URL('./hello.mjs',import.meta.url)),mainFormat:'module',output:binary}));const build=await spawnNode(['--build-sea',config]);assert.equal(build.code,0,build.stderr);const run=await promisify(execFile)(binary,['student'],{env:{...process.env,PATH:''}});console.log(run.stdout);assert.equal(run.stdout.trim(),'Hello, student!');''','The actual single executable builds and runs with PATH emptied, demonstrating that the Node runtime is embedded.',files={'hello.mjs':"const name=process.argv[2]??'world';console.log(`Hello, ${name}!`);"})
wat='''(module
(import "wasi_snapshot_preview1" "path_open" (func $open (param i32 i32 i32 i32 i32 i64 i64 i32 i32) (result i32)))
(import "wasi_snapshot_preview1" "fd_read" (func $read (param i32 i32 i32 i32) (result i32)))
(import "wasi_snapshot_preview1" "fd_write" (func $write (param i32 i32 i32 i32) (result i32)))
(import "wasi_snapshot_preview1" "fd_close" (func $close (param i32) (result i32)))
(memory (export "memory") 1)
(data (i32.const 0) "hello.txt")
(func (export "_start")
(call $open (i32.const 3) (i32.const 0) (i32.const 0) (i32.const 9) (i32.const 0) (i64.const 2) (i64.const 0) (i32.const 0) (i32.const 16)) drop
(i32.store (i32.const 32) (i32.const 128)) (i32.store (i32.const 36) (i32.const 128))
(call $read (i32.load (i32.const 16)) (i32.const 32) (i32.const 1) (i32.const 48)) drop
(i32.store (i32.const 64) (i32.const 128)) (i32.store (i32.const 68) (i32.load (i32.const 48)))
(call $write (i32.const 1) (i32.const 64) (i32.const 1) (i32.const 80)) drop
(call $close (i32.load (i32.const 16))) drop))'''
add(145,'''import wabtInit from 'wabt';import {WASI} from 'node:wasi';import {fileURLToPath} from 'node:url';import {readFile} from 'node:fs/promises';import assert from 'node:assert/strict';const wabt=await wabtInit(),parsed=wabt.parseWat('read.wat',await readFile(new URL('./read.wat',import.meta.url),'utf8'));const {buffer}=parsed.toBinary({});parsed.destroy();const wasi=new WASI({version:'preview1',args:['read'],preopens:{'/fixtures':fileURLToPath(new URL('./fixtures/',import.meta.url))}});const wasm=await WebAssembly.compile(buffer),instance=await WebAssembly.instantiate(wasm,wasi.getImportObject());assert.equal(wasi.start(instance),0);''','A real WASI program opens hello.txt through its preopened directory and prints Hello from WASI.','The default reproducible demo assembles the supplied WAT with wabt. The equivalent read.c and build.ps1 are supplied for the external WASI SDK route; do not claim the C compiler ran. Node WASI preopens are convenience mappings, not a comprehensive security sandbox.',files={'read.wat':wat,'fixtures/hello.txt':'Hello from WASI','read.c':'#include <stdio.h>\nint main(void){FILE *f=fopen("/fixtures/hello.txt","r");if(!f){perror("open");return 1;}char line[128];while(fgets(line,sizeof line,f))fputs(line,stdout);fclose(f);return 0;}','build.ps1':'$ErrorActionPreference="Stop"\n& "$env:WASI_SDK_PATH/bin/clang.exe" --target=wasm32-wasip1 -O2 -o read.wasm read.c','run-compiled.mjs':"import {readFile} from 'node:fs/promises';import {WASI} from 'node:wasi';const wasi=new WASI({version:'preview1',args:['read'],preopens:{'/fixtures':'./fixtures'}});const wasm=await WebAssembly.compile(await readFile('./read.wasm'));const instance=await WebAssembly.instantiate(wasm,wasi.getImportObject());process.exitCode=wasi.start(instance);"},deps=['wabt'])
add(146,'''import {assert,spawnNode} from '../../shared/lab.mjs';const r=await spawnNode(['--import','./register.mjs','main.mjs']);console.log(r.stdout,r.stderr);assert.equal(r.code,0,r.stderr);assert.ok(r.stdout.includes('course-app function'));assert.ok(r.stderr.includes('Unknown alias: @app/missing'));''','The preload hook resolves only explicit aliases, preserves node: imports and rejects an unknown alias.',files={'register.mjs':"import {registerHooks} from 'node:module';const aliases=new Map([['@app/config',new URL('./src/config.mjs',import.meta.url).href]]);registerHooks({resolve(specifier,context,nextResolve){if(specifier.startsWith('@app/')){const url=aliases.get(specifier);if(!url)throw Error(`Unknown alias: ${specifier}`);return{url,shortCircuit:true};}return nextResolve(specifier,context);}});",'main.mjs':"import {readFile} from 'node:fs/promises';import {appName} from '@app/config';console.log(appName,typeof readFile);await import('@app/missing').catch(e=>console.error(e.message));",'src/config.mjs':"export const appName='course-app';"})
add(147,'''import {dlopen,suffix} from 'node:ffi';import assert from 'node:assert/strict';const {lib,functions}=dlopen(`./mylib.${suffix}`,{add_i32:{arguments:['int32','int32'],return:'int32'}});try{const result=functions.add_i32(20,22);console.log(result);assert.equal(result,42);}finally{lib.close();}''','After building the supplied native C library for this OS/architecture, FFI returns 42 and closes its handle.','Windows: run cl /LD add.c /Fe:mylib.dll in Developer PowerShell. Linux: cc -shared -fPIC -o mylib.so add.c. macOS: cc -dynamiclib -o mylib.dylib add.c. Under the Permission Model grant --allow-ffi. Invalid signatures/pointers can crash the process; do not call after close.',files={'add.c':'#include <stdint.h>\n#if defined(_WIN32)\n#define EXPORT __declspec(dllexport)\n#else\n#define EXPORT\n#endif\nEXPORT int32_t add_i32(int32_t a,int32_t b){return a+b;}'},mode='native-tooling')
add(148,'''import vfs from 'node:vfs';import fs from 'node:fs';import assert from 'node:assert/strict';const fixture=vfs.create();fixture.mkdirSync('/config',{recursive:true});fixture.writeFileSync('/config/app.json','{"mode":"test"}');const root=fixture.mount();try{console.log(fs.readFileSync(`${root}/config/app.json`,'utf8'));}finally{fixture.unmount();}assert.equal(fixture.mounted,false);const provider=new vfs.MemoryProvider(),locked=vfs.create(provider);locked.writeFileSync('/seed.txt','initial');provider.setReadOnly();assert.throws(()=>locked.writeFileSync('/x.txt','fail'),{code:'EROFS'});console.log('unmounted=false; read-only writes throw EROFS');''','Mounted reads succeed, cleanup unmounts the fixture, and irreversible read-only mode rejects writes. VFS is not a sandbox.',flags=['--experimental-vfs'])
add(149,'''import {assert,spawnNode} from '../../shared/lab.mjs';const r=await spawnNode(['--experimental-bench','--bench','compare.mjs']);console.log(r.stdout,r.stderr);assert.equal(r.code,0,r.stderr);''','The actual experimental benchmark runner measures two equivalent string operations. Results depend on runtime and hardware.',files={'compare.mjs':"import {bench,suite} from 'node:bench';const parts=Array.from({length:1000},(_,i)=>`item${i}`),expected=parts.join(',');suite('join strings',()=>{bench('Array.join',{samples:30,warmup:10},b=>{b.start();const result=parts.join(',');b.end(1);if(result!==expected)throw Error('join mismatch');});bench('concatenation loop',{samples:30,warmup:10},b=>{b.start();let result=parts[0];for(let i=1;i<parts.length;i++)result+=`,${parts[i]}`;b.end(1);if(result!==expected)throw Error('loop mismatch');});});"})
add(150,'''import {assert,spawnNode} from '../../shared/lab.mjs';for(const [file,flags,expected] of [['iter.mjs',['--experimental-stream-iter'],'HELLO, ITERABLE STREAMS'],['classic.mjs',[],'HELLO, CLASSIC STREAMS']]){const r=await spawnNode([...flags,file]);console.log(r.stdout);assert.equal(r.code,0,r.stderr);assert.equal(r.stdout.trim(),expected);}''','Both actual stream interfaces produce uppercase output. The experimental iterable API and stable classic pipeline remain distinct.',files={'iter.mjs':"import {from,pull,text} from 'node:stream/iter';const upper=chunks=>chunks===null?null:chunks.map(c=>new TextEncoder().encode(new TextDecoder().decode(c).toUpperCase()));console.log(await text(pull(from('hello, iterable streams'),upper)));",'classic.mjs':"import {Readable,Transform} from 'node:stream';import {pipeline} from 'node:stream/promises';const upper=new Transform({transform(c,e,done){done(null,c.toString().toUpperCase());}});await pipeline(Readable.from(['hello, classic streams']),upper,process.stdout);"})
